#include <cstddef>
#include <iostream>

void func(int i) { std::cout << "Integer overload\n"; }
void func(int* p) { std::cout << "Pointer overload\n"; }

int main() {
    int* p1 = NULL; // OK, NULL converts to pointer type

    // Caution: NULL is an integer type, leading to ambiguity if not handled
    // func(NULL); // Might call integer overload depending on NULL's exact type

    func(nullptr); // C++11: Always calls pointer overload
    func(0);       // Always calls integer overload

    // int* p2 = (void*)0; // C++ ERROR: Cannot convert void* to int* implicitly
}
